package br.com.brindespro.quote;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.*;
@Entity @Table(name="quotes") public class Quote { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@Column(unique=true) public String number;@ManyToOne(optional=false) @JoinColumn(name="customer_id") public Customer customer;@Column(nullable=false) public String status="Registrado";@Column(name="order_status",nullable=false) public String orderStatus="RECEBIDO";@Column(name="expected_delivery_date") public java.time.LocalDate expectedDeliveryDate;@Column(name="tracking_code",length=180) public String trackingCode="";@Column(length=1000) public String notes="";@Column(name="internal_note",length=2000) public String internalNote="";@Column(nullable=false,precision=14,scale=2) public BigDecimal total=BigDecimal.ZERO;@Column(name="created_at",nullable=false) public OffsetDateTime createdAt=OffsetDateTime.now();@Column(name="updated_at",nullable=false) public OffsetDateTime updatedAt=OffsetDateTime.now();@OneToMany(mappedBy="quote",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) public Set<QuoteItem> items=new LinkedHashSet<>();protected Quote(){} public Quote(Customer customer,String notes){this.customer=customer;this.notes=notes;} }
